srcDoc.css:
/* 1. Reset the core container to absorb resizing without overflowing */
html, body, #root {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden !important; /* Force hide main scrollbars */
  -ms-overflow-style: none; /* Hide scrollbar for IE and Edge */
  scrollbar-width: none; /* Hide scrollbar for Firefox */
}

/* 2. Hide scrollbars for Chrome, Safari and Opera across ALL elements inside the widget */
::-webkit-scrollbar {
  display: none !important;
  width: 0px !important;
  height: 0px !important;
}

